/**
 * Sub packs (Daily Teaching System, Parts 3 and 5): /<locale>/sub-plans/<slug>.
 *
 * One school day of review for one grade, for the day the teacher is away: a worksheet for every block, a script for
 * the guest teacher, forms. The page renders one generated file per language:
 *
 *   content/sub-plans/packs.<loc>.json   GENERATED by scripts/sub-plans/assemble.js
 *   content/sub-plans/ui.<loc>.json      the page's and the guest teacher pages' own strings
 *
 * status 'pilot' = noindex, in no sitemap, linked from nowhere.
 */
import { pagePdf } from '@/lib/units';

export interface SubBlock {
  key: string;
  minutes: number;
  point: string;
  type: string;
  title: string;
  instruction: string;
  core: string;
  hard?: string;
  easy?: string;
  script: { say: string; first: string; stuck: string };
}
export interface SubPack {
  id: string;
  slug: string;
  status: 'pilot' | 'live';
  grade: string;
  position: 'early' | 'middle' | 'late';
  title: string;
  metaTitle: string;
  metaDescription: string;
  minutes: number;
  blocks: SubBlock[];
}
export type SubUi = Record<string, string>;

const cache = new Map<string, unknown>();
async function load<T>(key: string, importer: () => Promise<{ default: unknown }>): Promise<T | null> {
  if (cache.has(key)) return cache.get(key) as T;
  try {
    const mod = await importer();
    cache.set(key, mod.default);
    return mod.default as T;
  } catch {
    cache.set(key, null);
    return null;
  }
}
export async function getSubPacks(locale: string): Promise<SubPack[]> {
  const f = await load<{ packs: SubPack[] }>(`packs.${locale}`, () => import(`@/content/sub-plans/packs.${locale}.json`));
  return f?.packs ?? [];
}
export const getSubUi = (locale: string) => load<SubUi>(`ui.${locale}`, () => import(`@/content/sub-plans/ui.${locale}.json`));
export async function getSubPack(locale: string, slug: string): Promise<SubPack | null> {
  return (await getSubPacks(locale)).find((p) => p.slug === slug) ?? null;
}
export async function subPackSiblings(id: string, locales: readonly string[]): Promise<Record<string, string>> {
  const out: Record<string, string> = {};
  for (const l of locales) {
    const p = (await getSubPacks(l)).find((x) => x.id === id && x.status === 'live');
    if (p) out[l] = p.slug;
  }
  return out;
}

/** every worksheet of the pack in the order of the day: for everyone, easier, for early finishers */
export function subPackPdfList(locale: string, pack: SubPack): string[] {
  const out: string[] = [];
  for (const b of pack.blocks) { out.push(b.core); if (b.easy) out.push(b.easy); if (b.hard) out.push(b.hard); }
  return [...new Set(out)].map((slug) => pagePdf(locale, slug).replace(/^https?:\/\/[^/]+/, ''));
}
/** the Teacher-only file of a pack, as the gate knows it (lib/teacher-files.ts) */
export const subPackScriptFile = (pack: SubPack) => `sub-plans/${pack.id}/guest-teacher-pages`;
